using UnityEngine;
using UnityEditor;
using UnityEngine.SceneManagement;
using System;
using System.IO;
using System.Linq;
using ConRoi.Investigation.V36.R107;

namespace Unity.AI.Assistant.Agent.Dynamic.Extension.Editor
{
    internal class CommandScript : IRunCommand
    {
        public void Execute(ExecutionResult r)
        {
            if (Application.dataPath != "C:/ConRoi_CheckoutTest/Assets")
                throw new Exception("Wrong project");
            var s = UnityEngine.Object.FindFirstObjectByType<InvestigationSession>();
            if (!s || !s.SavePath.Contains("NavFixture_a789222"))
                throw new Exception("Wrong profile");
            if (Enumerable.Range(0, SceneManager.sceneCount).Any(i => SceneManager.GetSceneAt(i).isDirty))
                throw new Exception("Dirty scene; do not discard");
            File.WriteAllText("Test/Output/CleanCheckout/pre-skip-stop-live.json", JsonUtility.ToJson(s.data, true));
            File.WriteAllText("Test/Output/CleanCheckout/pre-skip-stop-context.txt", "page=" + s.Page + " profile=" + s.SavePath + " position=" + s.movement.transform.position);
            EditorApplication.isPlaying = false;
            r.Log("Preserved live state before stop; no scene save/discard. Restart only after clean Edit confirmed.");
        }
    }
}

